def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0)
                prev_bids.append(b)
                if opp.get('budget', 0) > 0:
                    strong_prev.append(b)

    if not alive:
        return max(0.0, min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    live_pressure = max(strong_prev) if strong_prev else highest_prev

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    danger = 0
    if hp <= 3 or no_water_days >= 2:
        danger = 2
    elif hp <= 5 or no_water_days >= 1:
        danger = 1

    rich_alive = 0
    for opp in alive:
        if opp.get('budget', 0) >= 200:
            rich_alive += 1

    target = 0.0

    if danger >= 2:
        target = max(62.0, live_pressure + 2.5)
        if scarcity == 2:
            target = max(target, 82.0)
    elif scarcity == 2:
        target = max(46.0, live_pressure + 1.5)
        if rich_alive >= 2:
            target = max(target, 72.0)
    elif scarcity == 1:
        target = max(30.0, live_pressure * 0.72)
        if live_pressure < 40:
            target = max(target, live_pressure + 2.0)
    else:
        target = max(12.0, live_pressure * 0.22)
        if rich_alive >= 2:
            target = min(target, 28.0)

    if day >= 8 and budget > 180:
        target += 6.0
    if day >= 9 and (hp <= 6 or no_water_days >= 1):
        target += 10.0

    if budget < 40:
        target = min(target, budget)
    elif budget < 90:
        target = min(target, 0.75 * budget)

    target = max(0.0, min(budget, target))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for o in alive_opponents:
        pt = o.get('previous_trace', {})
        if pt and pt.get('bid') is not None:
            try:
                prev_bids.append(float(pt['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Baseline aggressiveness: moderate to avoid budget collapse
    # Supply affects how many water units are likely available; higher supply => can bid lower.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Urgency based on hp and consecutive no-water days
    urgency = 0.0
    if hp <= 2.0:
        urgency += 0.9
    elif hp <= 4.0:
        urgency += 0.6
    elif hp <= 6.0:
        urgency += 0.35
    else:
        urgency += 0.15

    if no_water_days >= 2:
        urgency += 0.35
    elif no_water_days >= 1:
        urgency += 0.15

    # If opponents previously bid extremely high, try to undercut unless we are in danger.
    # Cindy/David were very high; Alex/Eric died. So we don't match extreme bids unless necessary.
    extreme_threshold = DAILY_SALARY * 0.95  # 85.5

    # Target bid computation
    if highest_prev_bid >= extreme_threshold:
        # If I'm healthy, bid around a fraction of salary; if low hp, bid closer to previous high.
        if hp > 5.0 and urgency < 0.6:
            target = DAILY_SALARY * (0.45 + 0.15 * (1.0 - supply_norm))
        else:
            # Bid slightly above second-highest to steal allocation
            target = max(second_prev_bid + 2.0, DAILY_SALARY * (0.7 + 0.2 * (1.0 - supply_norm)))
    else:
        # Not extreme yesterday: bid enough to be competitive but not wasteful
        target = DAILY_SALARY * (0.5 + 0.25 * (1.0 - supply_norm) + 0.2 * urgency)

    # Clamp to budget and keep within reasonable bounds
    target = max(0.0, target)
    # Never bid more than budget; also avoid bidding above 1.2*salary unless in critical hp
    critical = (hp <= 2.0 or no_water_days >= 3)
    cap = budget if critical else min(budget, DAILY_SALARY * 1.2)
    if cap <= 0.0:
        return 0.0

    bid = min(target, cap)

    # If budget is low, switch to survival-maximizing: bid a larger fraction of remaining budget.
    if budget < DAILY_SALARY * 0.6:
        bid = min(budget, budget * (0.75 + 0.25 * urgency))

    # Ensure bid is at least 1 when we can afford it, to avoid zero-lock.
    if bid < 1.0 and budget >= 1.0:
        bid = 1.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid_amount = DAILY_SALARY * 0.6

    if my_status['hp'] <= 2:
        bid_amount = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5:
        bid_amount = DAILY_SALARY * 0.8
    else:
        bid_amount = DAILY_SALARY * 0.5

    if highest_prev_bid > 0:
        if my_status['hp'] <= 5:
            bid_amount = max(bid_amount, highest_prev_bid + 5)
        else:
            bid_amount = max(bid_amount, highest_prev_bid * 0.9)

    supply = day_context['supply']
    if supply <= 18:
        bid_amount *= 1.05
    elif supply >= 22:
        bid_amount *= 0.95

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] <= 5:
        bid_amount = DAILY_SALARY * 0.99

    final_bid = min(my_status['budget'], bid_amount)

    return max(1.0, final_bid)
